class InventoryItem { final String id, name, slot; final int rarity, power; const InventoryItem({required this.id,required this.name,required this.slot,this.rarity=0,this.power=0}); Map<String,dynamic> toJson()=>{'id':id,'name':name,'slot':slot,'rarity':rarity,'power':power}; static InventoryItem? fromJson(dynamic raw){if(raw is! Map)return null; final id=raw['id'];final name=raw['name'];final slot=raw['slot'];if(id is! String||name is! String||slot is! String)return null;return InventoryItem(id:id,name:name,slot:slot,rarity:(raw['rarity'] as num?)?.toInt()??0,power:(raw['power'] as num?)?.toInt()??0);} }
class InventoryState { final List<InventoryItem> backpack=[], vault=[]; final Map<String,InventoryItem> equipped={}; int medkits=2, grenades=2, shards=0; bool equip(InventoryItem item){if(!backpack.any((e)=>e.id==item.id))return false;final old=equipped[item.slot];if(old!=null)backpack.add(old);backpack.removeWhere((e)=>e.id==item.id);equipped[item.slot]=item;return true;} void toVault(InventoryItem item){if(backpack.remove(item)){vault.add(item);}} void toBackpack(InventoryItem item){if(vault.remove(item)){backpack.add(item);}} Map<String,dynamic> toJson()=>{'backpack':backpack.map((e)=>e.toJson()).toList(),'vault':vault.map((e)=>e.toJson()).toList(),'equipped':equipped.map((k,v)=>MapEntry(k,v.toJson())),'medkits':medkits,'grenades':grenades,'shards':shards}; void loadJson(dynamic raw){if(raw is! Map)return;List<InventoryItem> parse(dynamic list)=> (list is List?list:const []).map(InventoryItem.fromJson).whereType<InventoryItem>().toList();backpack..clear()..addAll(parse(raw['backpack']));vault..clear()..addAll(parse(raw['vault']));equipped.clear();if(raw['equipped'] is Map)(raw['equipped'] as Map).forEach((k,v){final item=InventoryItem.fromJson(v);if(k is String&&item!=null)equipped[k]=item;});medkits=(raw['medkits'] as num?)?.toInt()??2;grenades=(raw['grenades'] as num?)?.toInt()??2;shards=(raw['shards'] as num?)?.toInt()??0;} }
